INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'metabolic',
  'dm_type2',
  ARRAY['DM']::diagnosis_type_enum[],
  'Type 2 Diabetes Mellitus',
  'Diabetes Melitus Tipe 2',
  'Program Jalan Kaki & Latihan Beban untuk DM Tipe 2',
  'pemula',
  'Pasien DM tipe 2 usia >40 tahun dengan aktivitas fisik rendah, tanpa komplikasi kardiovaskular berat',
  '[{"id": "hba1c", "label_id": "Menurunkan HbA1c"}, {"id": "insulin_sensitivity", "label_id": "Meningkatkan sensitivitas insulin"}, {"id": "weight", "label_id": "Membantu kontrol berat badan"}]'::jsonb,
  '{"frequency": "5x/minggu (aerobik) + 2-3x/minggu (resistance, hari non-berurutan)", "intensity": {"method": "RPE / Talk Test", "target": "RPE 11-13, sedang", "notes": "Masih bisa bicara, sedikit terengah"}, "time": "30-45 menit/sesi aerobik", "type": ["Jalan kaki", "Bersepeda statis", "Resistance training ringan"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan pelan 3-5 menit", "Putaran bahu dan pergelangan kaki", "Peregangan betis dan paha depan/belakang"]}'::jsonb,
  '{"description": "Kombinasi latihan aerobik intensitas sedang dan resistance training 2 set 8-12 repetisi untuk kelompok otot besar.", "weekly_progression": [{"period": "Hari 1", "duration_minutes": 15, "notes": "Jalan santai"}, {"period": "Hari 7", "duration_minutes": 20, "notes": "Tambah kecepatan bertahap"}, {"period": "Minggu 4", "duration_minutes": 30, "notes": "Target FITT tercapai"}, {"period": "Minggu 12", "duration_minutes": 45, "notes": "Pertahankan, variasikan jenis latihan"}], "resistance_details": [{"exercise": "Squat ke kursi", "muscle_group": "Quadriceps/Gluteus", "sets": 2, "reps": 10, "rest_seconds": 60, "notes": "Gunakan kursi untuk keamanan"}, {"exercise": "Wall push-up", "muscle_group": "Dada/Triceps", "sets": 2, "reps": 10, "rest_seconds": 60}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan 2-3 menit", "Napas dalam"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan hamstring", "Peregangan betis", "Peregangan bahu"]}'::jsonb,
  '[{"phase": "core", "label": "Squat ke kursi - posisi awal & akhir", "image_url": null, "video_url": null}]'::jsonb,
  '{"hipertensi": "Hindari manuver Valsava dan angkat beban maksimal", "neuropati_perifer": "Pilih latihan non-weight bearing (sepeda, kolam) bila ada luka/mati rasa kaki", "retinopati_proliferatif": "Hindari latihan intensitas tinggi dan manuver kepala ke bawah"}'::jsonb,
  '["Gula darah <70 mg/dL sebelum/selama latihan", "Gula darah >300 mg/dL disertai keton", "Nyeri dada", "Pusing atau pandangan kabur mendadak", "Sesak napas berat"]'::jsonb,
  '{"absolute": ["Gula darah >300 mg/dL dengan ketonuria", "Hipoglikemia belum teratasi"], "relative": ["Ulkus kaki diabetik aktif", "Retinopati proliferatif tidak terkontrol"]}'::jsonb,
  '[{"metric": "HbA1c", "direction": "decrease", "target": "<7%", "timeframe": "3 bulan"}, {"metric": "Gula darah puasa", "direction": "decrease", "target": "80-130 mg/dL", "timeframe": "berkelanjutan"}]'::jsonb,
  '{"trigger": "2 minggu berturut-turut tanpa keluhan/hipoglikemia", "action": "Tambah durasi 10% atau repetisi +2"}'::jsonb,
  'Cek gula darah sebelum dan sesudah latihan pada awal program. Bawa camilan mengandung karbohidrat sederhana bila berlatih lebih dari 30 menit. Hari pertama cukup berjalan santai 15 menit; bila sudah terasa ringan setelah satu minggu, tambah menjadi 20 menit.',
  'Sedikit latihan yang dilakukan rutin jauh lebih bermanfaat daripada latihan berat tapi sesekali.',
  '{"day_1": "15 menit", "day_7": "20 menit", "week_4": "30 menit", "week_12": "45 menit"}'::jsonb,
  ARRAY['ADA Standards of Care 2024','ACSM Exercise Testing and Prescription','PERKENI 2021']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'metabolic',
  'prediabetes',
  ARRAY['DM','OTHER']::diagnosis_type_enum[],
  'Prediabetes',
  'Prediabetes',
  'Program Aktivitas Fisik Pencegahan Progresi Prediabetes',
  'pemula',
  'Dewasa dengan gula darah puasa terganggu (IFG) atau toleransi glukosa terganggu (IGT), belum bergejala',
  '[{"id": "prevent_progression", "label_id": "Mencegah progresi menjadi DM tipe 2"}, {"id": "weight", "label_id": "Menurunkan berat badan 5-7%"}]'::jsonb,
  '{"frequency": "5x/minggu", "intensity": {"method": "RPE", "target": "11-14, sedang", "notes": "Total 150 menit/minggu"}, "time": "30 menit/sesi", "type": ["Jalan cepat", "Bersepeda", "Berenang"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan 3 menit", "Peregangan dinamis ringan"]}'::jsonb,
  '{"description": "Aktivitas aerobik intensitas sedang, dapat dipecah 10 menit x 3 sesi/hari bila belum terbiasa.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 20, "notes": "Bangun kebiasaan"}, {"period": "Minggu 3-6", "duration_minutes": 30, "notes": "Target harian tercapai"}], "resistance_details": [{"exercise": "Resistance band row", "muscle_group": "Punggung/Bisep", "sets": 2, "reps": 12, "rest_seconds": 45}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Peregangan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan paha", "Peregangan bahu"]}'::jsonb,
  '[]'::jsonb,
  '{"obesitas": "Pilih latihan low-impact (sepeda, kolam) untuk mengurangi beban sendi"}'::jsonb,
  '["Nyeri dada", "Sesak napas tidak wajar", "Pusing berat"]'::jsonb,
  '{"absolute": [], "relative": ["Penyakit kardiovaskular tidak terkontrol - perlu skrining dulu"]}'::jsonb,
  '[{"metric": "Gula darah puasa", "direction": "decrease", "target": "<100 mg/dL", "timeframe": "6 bulan"}, {"metric": "Berat badan", "direction": "decrease", "target": "-5% sampai -7%", "timeframe": "6 bulan"}]'::jsonb,
  '{"trigger": "Toleransi baik 2 minggu", "action": "Tambah 5 menit per sesi"}'::jsonb,
  'Aktivitas fisik teratur, meski ringan, dapat menurunkan risiko diabetes hingga hampir separuh. Mulai dari jalan kaki 20 menit dan tingkatkan bertahap.',
  'Mencegah lebih mudah daripada mengobati — setiap langkah hari ini adalah investasi kesehatan.',
  '{"day_1": "20 menit", "week_6": "30 menit"}'::jsonb,
  ARRAY['ADA 2024','CDC Physical Activity Guidelines']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'metabolic',
  'obesitas',
  ARRAY['OBESITY']::diagnosis_type_enum[],
  'Obesity',
  'Obesitas',
  'Program Latihan Low-Impact untuk Penurunan Berat Badan',
  'pemula',
  'Dewasa dengan IMT ≥30 kg/m², tanpa komplikasi ortopedi berat',
  '[{"id": "weight_loss", "label_id": "Menurunkan berat badan 5-10%"}, {"id": "functional_capacity", "label_id": "Meningkatkan kapasitas fungsional"}]'::jsonb,
  '{"frequency": "5-6x/minggu", "intensity": {"method": "RPE", "target": "10-13", "notes": "Mulai ringan, naik bertahap ke sedang"}, "time": "30-60 menit/sesi (boleh dipecah)", "type": ["Jalan kaki", "Berenang", "Sepeda statis", "Resistance training"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan pelan", "Mobilisasi sendi besar"]}'::jsonb,
  '{"description": "Prioritaskan aktivitas non-weight-bearing di awal (kolam, sepeda) untuk melindungi sendi, lalu tambah weight-bearing bertahap.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "2x15 menit/hari"}, {"period": "Minggu 8", "duration_minutes": 45, "notes": "Sesi kontinu"}], "resistance_details": [{"exercise": "Sit-to-stand", "muscle_group": "Quadriceps/Gluteus", "sets": 2, "reps": 8, "rest_seconds": 90}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Napas dalam"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan paha", "Peregangan punggung bawah"]}'::jsonb,
  '[]'::jsonb,
  '{"osteoartritis": "Utamakan latihan di air atau bersepeda untuk mengurangi beban sendi", "hipertensi": "Hindari menahan napas saat resistance training"}'::jsonb,
  '["Nyeri sendi berat", "Nyeri dada", "Sesak napas berlebihan", "Pusing"]'::jsonb,
  '{"absolute": ["Gagal jantung dekompensasi"], "relative": ["Osteoartritis lutut berat belum dievaluasi"]}'::jsonb,
  '[{"metric": "Berat badan", "direction": "decrease", "target": "-5% sampai -10%", "timeframe": "6 bulan"}, {"metric": "Lingkar perut", "direction": "decrease", "target": "sesuai target individual", "timeframe": "6 bulan"}]'::jsonb,
  '{"trigger": "2 minggu tanpa nyeri sendi/keluhan", "action": "Tambah durasi 10%"}'::jsonb,
  'Tidak perlu langsung berat. Mulai dari aktivitas yang ringan pada sendi seperti berenang atau bersepeda, lalu tingkatkan durasi secara bertahap setiap minggu.',
  'Penurunan berat badan yang bertahan lama dimulai dari kebiasaan kecil yang konsisten.',
  '{"day_1": "15 menit", "week_8": "45 menit"}'::jsonb,
  ARRAY['ACSM','WHO Physical Activity Guidelines']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
