INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'cardiovascular',
  'hipertensi',
  ARRAY['HT']::diagnosis_type_enum[],
  'Hypertension',
  'Hipertensi',
  'Program Aerobik Terkontrol untuk Hipertensi',
  'pemula',
  'Pasien hipertensi terkontrol (<160/100 mmHg) tanpa komplikasi organ target berat',
  '[{"id": "bp_reduction", "label_id": "Menurunkan tekanan darah"}, {"id": "cv_risk", "label_id": "Menurunkan risiko kardiovaskular"}]'::jsonb,
  '{"frequency": "5-7x/minggu (aerobik) + 2-3x/minggu resistance ringan", "intensity": {"method": "RPE", "target": "11-13, sedang", "notes": "Hindari intensitas berat"}, "time": "30 menit/sesi", "type": ["Jalan kaki", "Bersepeda", "Berenang"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan pelan 5 menit", "Peregangan ringan"]}'::jsonb,
  '{"description": "Aerobik kontinu intensitas sedang. Resistance training dengan beban ringan-sedang, hindari menahan napas.", "weekly_progression": [{"period": "Minggu 1", "duration_minutes": 15, "notes": "Mulai perlahan"}, {"period": "Minggu 6", "duration_minutes": 30, "notes": "Target tercapai"}], "resistance_details": [{"exercise": "Leg press ringan", "muscle_group": "Tungkai", "sets": 2, "reps": 12, "rest_seconds": 90, "notes": "Beban ringan, napas tidak ditahan"}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan hingga nadi turun"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan tungkai dan punggung"]}'::jsonb,
  '[]'::jsonb,
  '{"gagal_jantung": "Turunkan intensitas dan pantau gejala sesak", "ckd": "Sesuaikan cairan dan hindari dehidrasi"}'::jsonb,
  '["Nyeri dada", "Sakit kepala hebat mendadak", "Pandangan kabur", "TD sistolik >200 mmHg saat latihan", "Pusing berat"]'::jsonb,
  '{"absolute": ["TD istirahat >180/110 mmHg", "Krisis hipertensi"], "relative": ["Aritmia tidak terkontrol"]}'::jsonb,
  '[{"metric": "Tekanan darah", "direction": "decrease", "target": "<130/80 mmHg", "timeframe": "3 bulan"}]'::jsonb,
  '{"trigger": "TD stabil dan toleransi baik 2 minggu", "action": "Tambah durasi 10%"}'::jsonb,
  'Hindari menahan napas saat mengangkat beban (manuver Valsava) karena dapat menaikkan tekanan darah secara tiba-tiba. Latihan jalan kaki rutin adalah pilihan paling aman untuk memulai.',
  'Setiap langkah membantu jantung bekerja lebih ringan.',
  '{"day_1": "15 menit", "week_6": "30 menit"}'::jsonb,
  ARRAY['ESC/ESH Hypertension Guidelines','AHA','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'cardiovascular',
  'gagal_jantung_stabil',
  ARRAY['CHF']::diagnosis_type_enum[],
  'Stable Heart Failure',
  'Gagal Jantung Stabil',
  'Program Rehabilitasi Kardiak untuk Gagal Jantung Stabil (NYHA I-II)',
  'pemula',
  'Pasien gagal jantung NYHA kelas I-II, kondisi stabil ≥3 minggu, sudah dievaluasi dokter jantung',
  '[{"id": "functional_capacity", "label_id": "Meningkatkan kapasitas fungsional (VO2 peak)"}, {"id": "quality_of_life", "label_id": "Meningkatkan kualitas hidup"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "Borg Scale (RPE 6-20)", "target": "11-14", "notes": "Mulai sangat ringan, di bawah supervisi awal"}, "time": "20-30 menit/sesi, boleh interval", "type": ["Jalan kaki", "Sepeda statis", "Latihan interval"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan sangat pelan 5 menit", "Mobilisasi sendi"]}'::jsonb,
  '{"description": "Idealnya dimulai dalam program rehabilitasi kardiak terstruktur dengan supervisi. Gunakan interval kerja-istirahat bila toleransi rendah.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 10, "notes": "Interval 2 menit kerja/1 menit istirahat, dengan supervisi"}, {"period": "Minggu 8-12", "duration_minutes": 30, "notes": "Kontinu, mandiri bila stabil"}], "resistance_details": [{"exercise": "Resistance band ringan", "muscle_group": "Otot besar tungkai/lengan", "sets": 1, "reps": 10, "rest_seconds": 90, "notes": "Beban sangat ringan"}]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan sangat pelan", "Pantau gejala sesak"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan"]}'::jsonb,
  '[]'::jsonb,
  '{"ckd": "Perhatikan status cairan dan elektrolit", "aritmia": "Hentikan bila palpitasi tidak wajar"}'::jsonb,
  '["Sesak napas memberat mendadak", "Nyeri dada", "Berat badan naik >2 kg dalam 2-3 hari", "Edema tungkai memberat", "Pusing/nyaris pingsan", "Palpitasi"]'::jsonb,
  '{"absolute": ["Gagal jantung dekompensasi akut", "Aritmia tidak terkontrol", "Stenosis aorta berat simtomatik"], "relative": ["Perubahan status klinis dalam 3 hari terakhir"]}'::jsonb,
  '[{"metric": "Kapasitas fungsional (6MWT)", "direction": "increase", "target": "peningkatan jarak tempuh", "timeframe": "12 minggu"}, {"metric": "Berat badan harian", "direction": "maintain", "target": "stabil ±1 kg", "timeframe": "harian"}]'::jsonb,
  '{"trigger": "Stabil tanpa gejala 2 minggu, sesuai evaluasi dokter", "action": "Tambah durasi 5 menit"}'::jsonb,
  'Timbang berat badan setiap pagi. Jika naik lebih dari 2 kg dalam 2-3 hari atau sesak memberat, hentikan latihan dan segera hubungi dokter.',
  'Latihan yang tepat justru membuat jantung Anda lebih kuat, bukan lebih lelah.',
  '{"day_1": "10 menit (interval)", "week_12": "30 menit (kontinu)"}'::jsonb,
  ARRAY['ESC Heart Failure Guidelines','AHA Cardiac Rehabilitation']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'cardiovascular',
  'pjk',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Coronary Artery Disease',
  'Penyakit Jantung Koroner',
  'Program Rehabilitasi Kardiak Pasca PJK',
  'pemula',
  'Pasien pasca sindrom koroner akut/revaskularisasi, sudah menyelesaikan fase rehabilitasi awal di rumah sakit',
  '[{"id": "secondary_prevention", "label_id": "Pencegahan sekunder kejadian kardiovaskular"}, {"id": "functional_capacity", "label_id": "Meningkatkan kapasitas aerobik"}]'::jsonb,
  '{"frequency": "5x/minggu", "intensity": {"method": "HRR (Heart Rate Reserve)", "target": "40-70% HRR", "notes": "Sesuai hasil tes latihan (exercise stress test)"}, "time": "20-40 menit/sesi", "type": ["Jalan kaki", "Sepeda statis", "Treadmill"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan pelan", "Mobilisasi sendi"]}'::jsonb,
  '{"description": "Program bertahap dimulai dari fase rehabilitasi terawasi, lanjut ke latihan mandiri setelah stabil.", "weekly_progression": [{"period": "Minggu 1-4 (fase 2, terawasi)", "duration_minutes": 20, "notes": "Dengan monitoring EKG bila tersedia"}, {"period": "Minggu 12 (fase 3, mandiri)", "duration_minutes": 40, "notes": "Latihan mandiri dengan evaluasi berkala"}], "resistance_details": [{"exercise": "Resistance band", "muscle_group": "Otot besar", "sets": 2, "reps": 12, "rest_seconds": 90, "notes": "Dimulai setelah minggu ke-4"}]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Jalan pelan hingga nadi turun ke baseline"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan"]}'::jsonb,
  '[]'::jsonb,
  '{"diabetes": "Cek gula darah sebelum latihan", "hipertensi": "Pantau TD sebelum dan sesudah"}'::jsonb,
  '["Nyeri dada/angina", "Sesak napas tidak wajar", "Palpitasi", "Pusing", "Keringat dingin mendadak"]'::jsonb,
  '{"absolute": ["Angina tidak stabil", "Aritmia mengancam nyawa yang tidak terkontrol", "Stenosis aorta berat"], "relative": ["Belum dilakukan tes latihan"]}'::jsonb,
  '[{"metric": "Kapasitas fungsional (METs)", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}, {"metric": "Profil lipid & TD", "direction": "decrease", "target": "sesuai target pencegahan sekunder", "timeframe": "3-6 bulan"}]'::jsonb,
  '{"trigger": "Tanpa gejala pada intensitas saat ini selama 1-2 minggu", "action": "Naikkan target HR 5% HRR"}'::jsonb,
  'Program rehabilitasi jantung terbukti menurunkan risiko serangan jantung berulang. Ikuti tahapan dengan sabar, jangan memaksakan diri melebihi anjuran dokter.',
  'Pemulihan jantung adalah maraton, bukan sprint — konsistensi adalah kuncinya.',
  '{"day_1": "20 menit (terawasi)", "week_12": "40 menit (mandiri)"}'::jsonb,
  ARRAY['AHA/ACC Cardiac Rehabilitation','ESC Guidelines']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'cardiovascular',
  'penyakit_arteri_perifer',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Peripheral Artery Disease',
  'Penyakit Arteri Perifer',
  'Program Jalan Kaki Interval untuk Klaudikasio Intermiten',
  'pemula',
  'Pasien PAD dengan klaudikasio intermiten, ABI rendah, tanpa iskemia kritis tungkai',
  '[{"id": "walking_distance", "label_id": "Meningkatkan jarak berjalan bebas nyeri"}, {"id": "cv_risk", "label_id": "Menurunkan risiko kardiovaskular"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "Nyeri klaudikasio sebagai panduan", "target": "Jalan sampai nyeri sedang (3-4/5), istirahat, ulangi", "notes": "Supervised exercise therapy bila tersedia"}, "time": "30-60 menit total (termasuk istirahat)", "type": ["Jalan kaki interval (treadmill/jalan datar)"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan tungkai ringan"]}'::jsonb,
  '{"description": "Jalan kaki sampai timbul nyeri klaudikasio sedang, istirahat hingga reda, ulangi siklus.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 20, "notes": "Total waktu jalan (interval)"}, {"period": "Minggu 12", "duration_minutes": 50, "notes": "Total waktu jalan meningkat, jarak tanpa nyeri bertambah"}], "resistance_details": []}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Duduk dan istirahat", "Elevasi tungkai bila perlu"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan betis"]}'::jsonb,
  '[]'::jsonb,
  '{"dm": "Periksa kaki rutin untuk luka, gunakan alas kaki yang tepat", "ckd": "Pantau status cairan"}'::jsonb,
  '["Nyeri tungkai saat istirahat (bukan hanya saat aktivitas)", "Luka atau perubahan warna kulit kaki yang tidak sembuh", "Nyeri dada", "Sesak napas"]'::jsonb,
  '{"absolute": ["Iskemia kritis tungkai (nyeri istirahat, ulkus/gangren)"], "relative": ["Penyakit jantung tidak stabil"]}'::jsonb,
  '[{"metric": "Jarak berjalan bebas nyeri", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}, {"metric": "ABI (Ankle-Brachial Index)", "direction": "maintain", "target": "stabil/membaik", "timeframe": "6 bulan"}]'::jsonb,
  '{"trigger": "Toleransi baik 2 minggu", "action": "Tambah jumlah siklus interval"}'::jsonb,
  'Nyeri saat berjalan pada PAD sebenarnya adalah bagian dari terapi — berjalan sampai nyeri sedang lalu istirahat justru melatih pembuluh darah membentuk jalur baru.',
  'Setiap langkah, meski disertai nyeri ringan, adalah latihan yang memperkuat sirkulasi Anda.',
  '{"day_1": "20 menit total", "week_12": "50 menit total"}'::jsonb,
  ARRAY['ACC/AHA PAD Guidelines','ESC PAD Guidelines']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'renal',
  'ckd_non_dialysis',
  ARRAY['CKD','CKD_ND']::diagnosis_type_enum[],
  'Chronic Kidney Disease (Stage 3-4, non-dialysis)',
  'CKD Stadium 3-4 (Belum Dialisis)',
  'Program Aktivitas Fisik untuk CKD Pra-Dialisis',
  'pemula',
  'Pasien CKD stadium 3-4, stabil secara klinis, tanpa anemia berat tidak terkoreksi',
  '[{"id": "functional_capacity", "label_id": "Mempertahankan kapasitas fungsional dan massa otot"}, {"id": "bp_control", "label_id": "Membantu kontrol tekanan darah"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "RPE", "target": "11-13", "notes": "Sesuaikan dengan tingkat kelelahan harian"}, "time": "20-30 menit/sesi", "type": ["Jalan kaki", "Sepeda statis", "Resistance ringan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Peregangan ringan"]}'::jsonb,
  '{"description": "Intensitas disesuaikan dengan kadar hemoglobin dan tingkat kelelahan; hindari overtraining.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Sesuai toleransi"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap sesuai energi harian"}], "resistance_details": [{"exercise": "Resistance band ringan", "muscle_group": "Otot besar", "sets": 2, "reps": 10, "rest_seconds": 90}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan"]}'::jsonb,
  '[]'::jsonb,
  '{"anemia": "Turunkan intensitas bila Hb rendah, prioritaskan latihan ringan", "hipertensi": "Hindari manuver Valsava"}'::jsonb,
  '["Kelelahan ekstrem", "Sesak napas tidak wajar", "Nyeri dada", "Edema memberat", "Pusing berat"]'::jsonb,
  '{"absolute": ["Anemia berat tidak terkoreksi (sesuai penilaian dokter)", "Kondisi akut tidak stabil"], "relative": ["Kelelahan berat pada hari tertentu — sesuaikan dengan kondisi"]}'::jsonb,
  '[{"metric": "Kapasitas fungsional", "direction": "maintain", "target": "stabil/meningkat", "timeframe": "3 bulan"}, {"metric": "Tekanan darah", "direction": "decrease", "target": "sesuai target individual", "timeframe": "3 bulan"}]'::jsonb,
  '{"trigger": "Toleransi baik dan energi cukup 2 minggu", "action": "Tambah durasi 10%"}'::jsonb,
  'Sesuaikan latihan dengan tingkat kelelahan harian. Tidak perlu memaksakan target yang sama setiap hari — dengarkan tubuh Anda.',
  'Menjaga otot tetap aktif membantu tubuh Anda tetap kuat menghadapi perjalanan pengobatan.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['KDIGO Guidelines','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'renal',
  'hemodialisis',
  ARRAY['CKD_HD']::diagnosis_type_enum[],
  'Hemodialysis',
  'Hemodialisis',
  'Program Latihan Intradialitik dan Hari Non-Dialisis',
  'pemula',
  'Pasien hemodialisis rutin, hemodinamik stabil selama sesi HD',
  '[{"id": "functional_capacity", "label_id": "Meningkatkan kapasitas fungsional"}, {"id": "muscle_mass", "label_id": "Mencegah sarkopenia/wasting otot"}, {"id": "quality_of_life", "label_id": "Meningkatkan kualitas hidup"}]'::jsonb,
  '{"frequency": "3x/minggu (selaras jadwal HD) + hari non-dialisis ringan", "intensity": {"method": "RPE", "target": "11-13", "notes": "Intradialitik: 1-2 jam pertama sesi HD, intensitas ringan-sedang"}, "time": "20-30 menit", "type": ["Sepeda statis intradialitik", "Resistance band", "Jalan kaki (hari non-HD)"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi sendi ringan sambil duduk"]}'::jsonb,
  '{"description": "Latihan sepeda statis intradialitik pada 1-2 jam pertama sesi HD (saat hemodinamik paling stabil), atau latihan resistance ringan di hari non-dialisis.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 10, "notes": "Mulai sangat ringan"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap sesuai toleransi"}], "resistance_details": [{"exercise": "Resistance band duduk", "muscle_group": "Tungkai/lengan", "sets": 2, "reps": 10, "rest_seconds": 90, "notes": "Hindari lengan dengan akses vaskular (AV fistula)"}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Istirahat duduk", "Pantau tekanan darah"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan sambil duduk"]}'::jsonb,
  '[]'::jsonb,
  '{"av_fistula": "Jangan gunakan lengan dengan akses vaskular untuk resistance training", "hipotensi_intradialitik": "Hentikan bila tekanan darah turun signifikan"}'::jsonb,
  '["Hipotensi intradialitik (pusing, pandangan gelap)", "Kram otot berat", "Nyeri dada", "Sesak napas", "Palpitasi"]'::jsonb,
  '{"absolute": ["Hemodinamik tidak stabil selama sesi HD", "2 jam terakhir sesi HD (risiko hipotensi lebih tinggi)"], "relative": ["Akses vaskular baru (<2 minggu)"]}'::jsonb,
  '[{"metric": "Kapasitas fungsional (6MWT)", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "3 bulan"}, {"metric": "Massa otot", "direction": "maintain", "target": "stabil/meningkat", "timeframe": "3-6 bulan"}]'::jsonb,
  '{"trigger": "Hemodinamik stabil dan toleransi baik 2 minggu", "action": "Tambah durasi 5 menit"}'::jsonb,
  'Latihan ringan selama dua jam pertama sesi cuci darah justru dapat membantu tubuh Anda tetap bugar dan mencegah pengecilan otot.',
  'Menjaga aktivitas selama terapi dialisis adalah investasi untuk kemandirian Anda sehari-hari.',
  '{"day_1": "10 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['KDIGO','ISRNM Guidelines on Exercise in CKD']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'renal',
  'peritoneal_dialisis',
  ARRAY['CKD_PD']::diagnosis_type_enum[],
  'Peritoneal Dialysis',
  'Peritoneal Dialisis',
  'Program Latihan Ringan untuk Pasien Peritoneal Dialisis',
  'pemula',
  'Pasien CAPD/APD stabil, tanpa peritonitis aktif',
  '[{"id": "functional_capacity", "label_id": "Mempertahankan kapasitas fungsional"}, {"id": "muscle_mass", "label_id": "Mencegah kehilangan massa otot"}]'::jsonb,
  '{"frequency": "4-5x/minggu", "intensity": {"method": "RPE", "target": "10-13", "notes": "Ringan hingga sedang"}, "time": "20-30 menit/sesi", "type": ["Jalan kaki", "Resistance ringan", "Peregangan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi ringan"]}'::jsonb,
  '{"description": "Hindari latihan yang meningkatkan tekanan intra-abdomen berlebihan (mengangkat beban berat, sit-up penuh) karena risiko kebocoran dialisat/hernia.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Ringan"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap"}], "resistance_details": [{"exercise": "Resistance band tungkai (posisi berdiri/duduk)", "muscle_group": "Tungkai", "sets": 2, "reps": 10, "rest_seconds": 90, "notes": "Hindari menahan napas/mengejan"}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan, hindari fleksi perut berlebihan"]}'::jsonb,
  '[]'::jsonb,
  '{"hernia_risiko": "Hindari latihan yang meningkatkan tekanan intra-abdomen", "kateter_abdomen": "Lindungi area kateter dari benturan"}'::jsonb,
  '["Nyeri perut mendadak", "Cairan dialisat keruh (tanda peritonitis — segera ke fasilitas kesehatan)", "Kebocoran cairan di sekitar kateter", "Sesak napas", "Nyeri dada"]'::jsonb,
  '{"absolute": ["Peritonitis aktif", "Kebocoran dialisat aktif"], "relative": ["Pasca insersi kateter <4 minggu — hindari latihan berat"]}'::jsonb,
  '[{"metric": "Kapasitas fungsional", "direction": "maintain", "target": "stabil/meningkat", "timeframe": "3 bulan"}]'::jsonb,
  '{"trigger": "Stabil tanpa keluhan abdomen 2 minggu", "action": "Tambah durasi 10%"}'::jsonb,
  'Hindari gerakan yang membuat perut terasa tertekan kuat, seperti mengangkat beban berat, untuk melindungi area kateter dan mencegah hernia.',
  'Aktivitas ringan yang konsisten membantu tubuh Anda tetap bertenaga menjalani terapi.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['ISPD Guidelines','KDIGO']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'respiratory',
  'ppok',
  ARRAY['COPD']::diagnosis_type_enum[],
  'COPD',
  'Penyakit Paru Obstruktif Kronik (PPOK)',
  'Program Rehabilitasi Paru untuk PPOK',
  'pemula',
  'Pasien PPOK stabil (bukan eksaserbasi akut), GOLD grade A-C',
  '[{"id": "dyspnea", "label_id": "Mengurangi sesak napas saat aktivitas"}, {"id": "functional_capacity", "label_id": "Meningkatkan toleransi aktivitas"}]'::jsonb,
  '{"frequency": "3-5x/minggu (aerobik) + 2-3x/minggu (otot pernapasan & resistance)", "intensity": {"method": "Skala Sesak Borg (0-10)", "target": "4-6/10 (sedang-berat)", "notes": "Latihan interval bila sesak berat pada latihan kontinu"}, "time": "20-30 menit/sesi", "type": ["Jalan kaki", "Sepeda statis", "Latihan pernapasan (pursed-lip breathing)"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Latihan pernapasan diafragma", "Mobilisasi ringan"]}'::jsonb,
  '{"description": "Kombinasi latihan aerobik dan latihan otot pernapasan (pursed-lip breathing, diaphragmatic breathing). Gunakan interval bila sesak signifikan.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 10, "notes": "Interval singkat dengan istirahat"}, {"period": "Minggu 8-12", "duration_minutes": 30, "notes": "Kontinu, sesuai toleransi"}], "resistance_details": [{"exercise": "Resistance band lengan/tungkai", "muscle_group": "Otot besar perifer", "sets": 2, "reps": 10, "rest_seconds": 60, "notes": "Membantu efisiensi energi sehari-hari"}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Pursed-lip breathing", "Duduk istirahat"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan dada dan bahu"]}'::jsonb,
  '[]'::jsonb,
  '{"hipoksemia": "Gunakan oksigen suplemental saat latihan bila diresepkan dokter", "osteoporosis_komorbid": "Hindari latihan high-impact"}'::jsonb,
  '["Sesak napas berat tidak membaik dengan istirahat", "Saturasi oksigen turun signifikan (sesuai ambang yang ditetapkan dokter)", "Nyeri dada", "Sianosis (bibir/kuku kebiruan)", "Kebingungan mendadak"]'::jsonb,
  '{"absolute": ["Eksaserbasi akut PPOK", "Gagal napas akut"], "relative": ["Aritmia tidak terkontrol"]}'::jsonb,
  '[{"metric": "Toleransi aktivitas (6MWT)", "direction": "increase", "target": "peningkatan jarak tempuh", "timeframe": "8-12 minggu"}, {"metric": "Skor sesak (mMRC)", "direction": "decrease", "target": "penurunan skor", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Sesak terkontrol pada intensitas saat ini selama 1-2 minggu", "action": "Tambah durasi 5 menit atau kurangi interval istirahat"}'::jsonb,
  'Gunakan teknik pernapasan bibir mengerucut (pursed-lip breathing) saat merasa sesak: tarik napas lewat hidung, hembuskan perlahan lewat mulut seperti meniup lilin.',
  'Latihan rutin membantu paru-paru Anda bekerja lebih efisien, sehingga aktivitas sehari-hari terasa lebih ringan.',
  '{"day_1": "10 menit (interval)", "week_12": "30 menit (kontinu)"}'::jsonb,
  ARRAY['GOLD Guidelines','American Thoracic Society Pulmonary Rehabilitation']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'respiratory',
  'asma',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Asthma',
  'Asma',
  'Program Aktivitas Fisik Terkontrol untuk Asma',
  'pemula',
  'Pasien asma terkontrol baik/sebagian, tanpa serangan dalam 4 minggu terakhir',
  '[{"id": "cardio_fitness", "label_id": "Meningkatkan kebugaran kardiorespirasi"}, {"id": "symptom_control", "label_id": "Menjaga kontrol gejala saat beraktivitas"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "RPE", "target": "11-14", "notes": "Pemanasan lebih panjang untuk mencegah bronkokonstriksi akibat latihan"}, "time": "20-30 menit/sesi", "type": ["Berenang", "Jalan kaki", "Bersepeda"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Pemanasan bertahap 10 menit (lebih panjang dari biasa)", "Latihan pernapasan"]}'::jsonb,
  '{"description": "Pemanasan panjang penting untuk mencegah exercise-induced bronchoconstriction. Bawa inhaler pereda (reliever) selalu.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Sesuai toleransi"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap"}], "resistance_details": []}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Pendinginan bertahap (tidak berhenti mendadak)", "Latihan pernapasan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan dada"]}'::jsonb,
  '[]'::jsonb,
  '{"alergi_lingkungan": "Hindari latihan luar ruangan saat kadar polusi/serbuk sari tinggi atau udara sangat dingin/kering"}'::jsonb,
  '["Mengi/sesak yang tidak membaik dengan inhaler pereda", "Sulit bicara karena sesak", "Bibir/kuku kebiruan", "Batuk berat tidak berhenti"]'::jsonb,
  '{"absolute": ["Serangan asma akut", "Asma tidak terkontrol"], "relative": ["Infeksi saluran napas aktif"]}'::jsonb,
  '[{"metric": "Kontrol gejala (ACT score)", "direction": "increase", "target": "skor terkontrol baik", "timeframe": "berkelanjutan"}, {"metric": "Kapasitas aerobik", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Tanpa gejala saat latihan selama 2 minggu", "action": "Tambah durasi 10%"}'::jsonb,
  'Selalu bawa inhaler pereda saat berolahraga. Pemanasan yang cukup panjang membantu mencegah sesak napas yang dipicu oleh latihan.',
  'Dengan kontrol yang baik, asma tidak menghalangi Anda untuk tetap aktif dan bugar.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['GINA (Global Initiative for Asthma)','American Thoracic Society']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'respiratory',
  'long_covid',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Long COVID',
  'Long COVID',
  'Program Pemulihan Bertahap Pasca COVID-19 (Long COVID)',
  'pemula',
  'Pasien dengan gejala menetap >12 minggu pasca infeksi COVID-19, termasuk kelelahan dan sesak napas',
  '[{"id": "fatigue", "label_id": "Mengurangi kelelahan pasca-eksersional"}, {"id": "functional_capacity", "label_id": "Memulihkan kapasitas fungsional secara bertahap"}]'::jsonb,
  '{"frequency": "Individual, mulai 2-3x/minggu", "intensity": {"method": "RPE dengan prinsip pacing", "target": "<12 (ringan)", "notes": "Prioritaskan pacing, hindari ''push-crash'' cycle"}, "time": "5-15 menit/sesi di awal, sangat bertahap", "type": ["Jalan kaki ringan", "Latihan pernapasan", "Peregangan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Latihan pernapasan tenang"]}'::jsonb,
  '{"description": "PENTING: skrining PEM (Post-Exertional Malaise) terlebih dahulu. Jika ada PEM, gunakan prinsip pacing energy conservation, BUKAN peningkatan latihan bertahap standar — prioritaskan istirahat dan aktivitas dalam batas energi, bukan graded exercise therapy.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 5, "notes": "Sangat ringan, evaluasi respons 24-48 jam"}, {"period": "Minggu 8+", "duration_minutes": 15, "notes": "Naik HANYA jika tidak ada tanda PEM"}], "resistance_details": []}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Istirahat total", "Pantau gejala 24-48 jam berikutnya"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan sangat ringan"]}'::jsonb,
  '[]'::jsonb,
  '{"pem_positif": "Hentikan pendekatan peningkatan bertahap, fokus pada pacing dan konservasi energi, rujuk ke spesialis"}'::jsonb,
  '["Kelelahan hebat >24 jam setelah aktivitas (PEM)", "Sesak napas memberat", "Nyeri dada", "Palpitasi", "Pusing berat/nyaris pingsan", "Kabut otak (brain fog) memberat"]'::jsonb,
  '{"absolute": ["Tanda PEM (Post-Exertional Malaise) signifikan — hindari graded exercise standar"], "relative": ["Gejala kardiovaskular belum dievaluasi"]}'::jsonb,
  '[{"metric": "Tingkat kelelahan harian", "direction": "decrease", "target": "skala kelelahan menurun", "timeframe": "individual, bisa berbulan-bulan"}, {"metric": "Toleransi aktivitas", "direction": "increase", "target": "peningkatan sangat bertahap tanpa PEM", "timeframe": "individual"}]'::jsonb,
  '{"trigger": "Tidak ada tanda PEM 24-48 jam setelah aktivitas, konsisten 2 minggu", "action": "Tambah durasi sangat kecil (1-2 menit)"}'::jsonb,
  'Pemulihan Long COVID berbeda dari latihan biasa — prinsip utamanya adalah ''pacing'': lakukan aktivitas dalam batas energi Anda, istirahat sebelum lelah, bukan sesudahnya. Jangan memaksakan diri meski merasa ''hari baik''.',
  'Pemulihan bukan tentang seberapa cepat, tapi seberapa konsisten Anda menjaga keseimbangan energi.',
  '{"day_1": "5 menit", "week_8_plus": "15 menit (jika tanpa PEM)"}'::jsonb,
  ARRAY['NICE Guidelines on Long COVID','WHO Rehabilitation Guidance']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'musculoskeletal',
  'oa_lutut',
  ARRAY['OTHER','GERIATRIC']::diagnosis_type_enum[],
  'Knee Osteoarthritis',
  'Osteoartritis Lutut',
  'Program Latihan Low-Impact untuk Osteoartritis Lutut',
  'pemula',
  'Pasien osteoartritis lutut derajat ringan-sedang, nyeri terkontrol',
  '[{"id": "pain", "label_id": "Mengurangi nyeri lutut"}, {"id": "muscle_strength", "label_id": "Menguatkan otot quadriceps penstabil lutut"}, {"id": "function", "label_id": "Meningkatkan fungsi berjalan"}]'::jsonb,
  '{"frequency": "4-5x/minggu (aerobik) + 2-3x/minggu (penguatan)", "intensity": {"method": "RPE / skala nyeri", "target": "Nyeri ≤3/10 selama latihan", "notes": "Boleh sedikit nyeri ringan, hentikan bila nyeri tajam"}, "time": "20-30 menit/sesi", "type": ["Berenang", "Sepeda statis", "Latihan penguatan quadriceps"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi lutut ringan", "Jalan pelan"]}'::jsonb,
  '{"description": "Prioritaskan aktivitas low-impact (air, sepeda) dan latihan penguatan otot sekitar lutut untuk mengurangi beban sendi.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Ringan"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap"}], "resistance_details": [{"exercise": "Straight leg raise", "muscle_group": "Quadriceps", "sets": 2, "reps": 10, "rest_seconds": 60}, {"exercise": "Mini squat (setengah)", "muscle_group": "Quadriceps/Gluteus", "sets": 2, "reps": 10, "rest_seconds": 60}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Kompres dingin bila perlu"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan hamstring dan quadriceps ringan"]}'::jsonb,
  '[{"phase": "core", "label": "Straight leg raise - posisi awal & akhir", "image_url": null, "video_url": null}]'::jsonb,
  '{"obesitas": "Latihan di air untuk mengurangi beban sendi", "instabilitas_sendi": "Gunakan brace/penyangga sesuai anjuran fisioterapis"}'::jsonb,
  '["Nyeri tajam mendadak", "Bengkak signifikan setelah latihan", "Lutut mengunci atau tidak bisa digerakkan", "Kemerahan dan hangat pada sendi (curiga infeksi/flare)"]'::jsonb,
  '{"absolute": ["Flare akut dengan tanda infeksi sendi"], "relative": ["Nyeri berat tidak terkontrol - evaluasi dulu"]}'::jsonb,
  '[{"metric": "Skor nyeri (VAS)", "direction": "decrease", "target": "penurunan skor nyeri", "timeframe": "8-12 minggu"}, {"metric": "Kekuatan quadriceps", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Nyeri terkontrol dan toleransi baik 2 minggu", "action": "Tambah repetisi +2 atau durasi 10%"}'::jsonb,
  'Latihan tidak akan memperparah osteoartritis, justru otot yang kuat membantu melindungi sendi. Nyeri ringan setelah latihan yang mereda dalam 24 jam adalah wajar.',
  'Otot yang kuat adalah penyangga terbaik untuk lutut Anda.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['OARSI Guidelines','American College of Rheumatology','NICE']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'musculoskeletal',
  'nyeri_punggung_bawah',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Low Back Pain',
  'Nyeri Punggung Bawah',
  'Program Latihan Penguatan Core untuk Nyeri Punggung Bawah Kronik Non-Spesifik',
  'pemula',
  'Dewasa dengan nyeri punggung bawah kronik non-spesifik (>12 minggu), tanpa red flag neurologis',
  '[{"id": "pain", "label_id": "Mengurangi nyeri punggung"}, {"id": "core_strength", "label_id": "Menguatkan otot core/penyangga tulang belakang"}, {"id": "function", "label_id": "Meningkatkan fungsi aktivitas harian"}]'::jsonb,
  '{"frequency": "4-5x/minggu", "intensity": {"method": "Skala nyeri", "target": "Nyeri ≤3/10", "notes": "Tetap aktif, hindari bed rest berkepanjangan"}, "time": "20-30 menit/sesi", "type": ["Jalan kaki", "Latihan penguatan core", "Yoga/Pilates ringan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Cat-cow stretch"]}'::jsonb,
  '{"description": "Fokus pada penguatan otot core (transversus abdominis, multifidus) dan tetap aktif secara umum.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Latihan dasar core"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Tambah variasi dan repetisi"}], "resistance_details": [{"exercise": "Bird-dog", "muscle_group": "Core/punggung bawah", "sets": 2, "reps": 10, "rest_seconds": 45}, {"exercise": "Bridge (pelvic tilt)", "muscle_group": "Gluteus/Core", "sets": 2, "reps": 10, "rest_seconds": 45}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan", "Relaksasi"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Child''s pose", "Peregangan hamstring"]}'::jsonb,
  '[{"phase": "core", "label": "Bird-dog - posisi awal & akhir", "image_url": null, "video_url": null}]'::jsonb,
  '{"osteoporosis": "Hindari fleksi tulang belakang berlebihan dan gerakan memutar mendadak", "kehamilan": "Hindari posisi terlentang lama setelah trimester 1"}'::jsonb,
  '["Nyeri menjalar ke tungkai disertai kelemahan/mati rasa", "Gangguan buang air kecil/besar (curiga cauda equina — kegawatdaruratan)", "Demam disertai nyeri punggung", "Nyeri malam hari yang tidak membaik"]'::jsonb,
  '{"absolute": ["Tanda cauda equina syndrome (segera rujuk gawat darurat)", "Fraktur tulang belakang belum stabil"], "relative": ["Nyeri radikular akut berat"]}'::jsonb,
  '[{"metric": "Skor nyeri (VAS)", "direction": "decrease", "target": "penurunan skor", "timeframe": "6-8 minggu"}, {"metric": "Fungsi (Oswestry Disability Index)", "direction": "decrease", "target": "penurunan skor disabilitas", "timeframe": "8-12 minggu"}]'::jsonb,
  '{"trigger": "Nyeri terkontrol 2 minggu", "action": "Tambah repetisi atau variasi latihan"}'::jsonb,
  'Tetap aktif adalah kunci pemulihan nyeri punggung — bed rest berkepanjangan justru memperlambat pemulihan. Nyeri ringan saat mulai bergerak adalah normal dan biasanya mereda.',
  'Gerakan adalah obat terbaik untuk punggung yang kaku.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['NICE Low Back Pain Guidelines','American College of Physicians']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'musculoskeletal',
  'osteoporosis',
  ARRAY['OTHER','GERIATRIC']::diagnosis_type_enum[],
  'Osteoporosis',
  'Osteoporosis',
  'Program Latihan Weight-Bearing dan Keseimbangan untuk Osteoporosis',
  'pemula',
  'Pasien osteoporosis/osteopenia, risiko jatuh perlu dinilai terlebih dahulu',
  '[{"id": "bone_density", "label_id": "Mempertahankan/meningkatkan densitas tulang"}, {"id": "fall_prevention", "label_id": "Mengurangi risiko jatuh"}]'::jsonb,
  '{"frequency": "3-4x/minggu (weight-bearing) + 2x/minggu (keseimbangan)", "intensity": {"method": "RPE", "target": "11-13", "notes": "Hindari gerakan fleksi tulang belakang berlebihan dan high-impact bila risiko fraktur tinggi"}, "time": "20-30 menit/sesi", "type": ["Jalan kaki", "Latihan beban ringan-sedang", "Latihan keseimbangan (Tai Chi)"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Mobilisasi sendi"]}'::jsonb,
  '{"description": "Latihan weight-bearing (menahan berat tubuh sendiri) merangsang pembentukan tulang. Hindari gerakan memutar/membungkuk tulang belakang secara tiba-tiba.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Ringan"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap"}], "resistance_details": [{"exercise": "Squat ke kursi", "muscle_group": "Tungkai", "sets": 2, "reps": 10, "rest_seconds": 60}, {"exercise": "Heel raise", "muscle_group": "Betis", "sets": 2, "reps": 12, "rest_seconds": 45}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan lembut, hindari fleksi tulang belakang dalam"]}'::jsonb,
  '[]'::jsonb,
  '{"risiko_jatuh_tinggi": "Latihan keseimbangan dengan pegangan/pendamping, hindari latihan sendirian", "kifosis_berat": "Hindari sit-up dan fleksi tulang belakang"}'::jsonb,
  '["Nyeri tulang belakang mendadak tanpa trauma jelas (curiga fraktur kompresi)", "Nyeri hebat setelah jatuh/benturan ringan", "Penurunan tinggi badan mendadak disertai nyeri"]'::jsonb,
  '{"absolute": ["Fraktur kompresi akut belum stabil"], "relative": ["Risiko jatuh tinggi belum dievaluasi/diintervensi"]}'::jsonb,
  '[{"metric": "Risiko jatuh (skor fungsional)", "direction": "decrease", "target": "penurunan risiko", "timeframe": "12 minggu"}, {"metric": "Densitas tulang (DXA)", "direction": "maintain", "target": "stabil/meningkat", "timeframe": "1-2 tahun"}]'::jsonb,
  '{"trigger": "Tanpa nyeri dan stabil 2 minggu", "action": "Tambah beban ringan atau repetisi"}'::jsonb,
  'Latihan menahan berat badan seperti berjalan dan naik-turun tangga membantu memperlambat pengeroposan tulang. Hindari gerakan membungkuk dan memutar tulang belakang secara tiba-tiba.',
  'Tulang yang aktif adalah tulang yang lebih kuat — gerakan hari ini melindungi kemandirian Anda esok hari.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['National Osteoporosis Foundation','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'musculoskeletal',
  'sarcopenia',
  ARRAY['SARCOPENIA']::diagnosis_type_enum[],
  'Sarcopenia',
  'Sarkopenia',
  'Program Resistance Training untuk Sarkopenia',
  'pemula',
  'Lansia dengan penurunan massa dan kekuatan otot (sarkopenia), fungsional cukup untuk latihan mandiri/terdampingi',
  '[{"id": "muscle_mass", "label_id": "Meningkatkan massa otot"}, {"id": "muscle_strength", "label_id": "Meningkatkan kekuatan otot"}, {"id": "function", "label_id": "Meningkatkan kemampuan fungsional (berjalan, bangun dari kursi)"}]'::jsonb,
  '{"frequency": "2-3x/minggu (resistance) + aktivitas harian", "intensity": {"method": "RPE", "target": "12-15", "notes": "Progressive resistance training dengan beban meningkat bertahap"}, "time": "20-30 menit/sesi", "type": ["Resistance training", "Latihan fungsional (sit-to-stand)"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi sendi", "Jalan pelan"]}'::jsonb,
  '{"description": "Progressive resistance training adalah intervensi paling efektif untuk sarkopenia, ditambah asupan protein cukup (koordinasi dengan Meal Plan).", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Beban ringan, fokus teknik"}, {"period": "Minggu 12", "duration_minutes": 30, "notes": "Beban ditingkatkan bertahap"}], "resistance_details": [{"exercise": "Sit-to-stand", "muscle_group": "Quadriceps/Gluteus", "sets": 2, "reps": 10, "rest_seconds": 90}, {"exercise": "Resistance band row", "muscle_group": "Punggung/Bisep", "sets": 2, "reps": 10, "rest_seconds": 90}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan seluruh tubuh"]}'::jsonb,
  '[{"phase": "core", "label": "Sit-to-stand - posisi awal & akhir", "image_url": null, "video_url": null}]'::jsonb,
  '{"frailty": "Mulai dengan latihan duduk/dibantu, tingkatkan sangat bertahap", "risiko_jatuh": "Latihan dengan pengawasan atau pegangan"}'::jsonb,
  '["Nyeri dada", "Pusing berat", "Kelelahan ekstrem tidak wajar", "Jatuh saat latihan"]'::jsonb,
  '{"absolute": ["Kondisi akut tidak stabil"], "relative": ["Frailty berat - mulai dengan supervisi ketat"]}'::jsonb,
  '[{"metric": "Kekuatan genggam (handgrip strength)", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}, {"metric": "Kecepatan jalan", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Toleransi baik dan teknik benar 2 minggu", "action": "Tambah beban/resistensi 5-10%"}'::jsonb,
  'Latihan beban, meski ringan, adalah cara paling efektif menjaga otot tetap kuat seiring bertambahnya usia. Pastikan asupan protein cukup untuk mendukung pembentukan otot.',
  'Otot yang kuat menjaga kemandirian Anda dalam beraktivitas sehari-hari.',
  '{"day_1": "15 menit", "week_12": "30 menit"}'::jsonb,
  ARRAY['Asian Working Group for Sarcopenia (AWGS)','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'neurology',
  'parkinson',
  ARRAY['OTHER','GERIATRIC']::diagnosis_type_enum[],
  'Parkinson''s Disease',
  'Penyakit Parkinson',
  'Program Latihan Fungsional dan Keseimbangan untuk Parkinson',
  'pemula',
  'Pasien Parkinson stadium ringan-sedang (Hoehn & Yahr I-III), mampu berjalan dengan/tanpa alat bantu',
  '[{"id": "mobility", "label_id": "Mempertahankan mobilitas dan gaya berjalan"}, {"id": "balance", "label_id": "Meningkatkan keseimbangan, mengurangi risiko jatuh"}, {"id": "quality_of_life", "label_id": "Meningkatkan kualitas hidup"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "RPE", "target": "12-14", "notes": "Lakukan saat efek obat optimal (''on'' period)"}, "time": "30-45 menit/sesi", "type": ["Latihan gaya berjalan (big steps)", "Tai Chi", "Boxing non-kontak", "Sepeda statis"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Mobilisasi sendi", "Latihan rotasi tubuh"]}'::jsonb,
  '{"description": "Fokus pada latihan amplitudo besar (gerakan besar dan disengaja), latihan keseimbangan, dan latihan ritmis (musik/hitungan) untuk membantu inisiasi gerakan.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 20, "notes": "Latihan dasar dengan pendamping"}, {"period": "Minggu 12", "duration_minutes": 45, "notes": "Program terstruktur, bisa mandiri sesuai evaluasi"}], "resistance_details": [{"exercise": "Sit-to-stand", "muscle_group": "Tungkai", "sets": 2, "reps": 10, "rest_seconds": 60}]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Peregangan", "Latihan relaksasi"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan fleksor panggul dan dada (sering kaku pada Parkinson)"]}'::jsonb,
  '[]'::jsonb,
  '{"freezing_gait": "Gunakan isyarat visual/auditori (cue) untuk membantu inisiasi langkah", "risiko_jatuh": "Latihan dengan pendamping atau di area aman berpegangan"}'::jsonb,
  '["Jatuh berulang", "Nyeri dada", "Pusing berat/hipotensi ortostatik", "Kebingungan mendadak"]'::jsonb,
  '{"absolute": ["Kondisi kardiovaskular tidak stabil"], "relative": ["Freezing gait berat belum dievaluasi terapis"]}'::jsonb,
  '[{"metric": "Keseimbangan (Berg Balance Scale)", "direction": "increase", "target": "peningkatan skor", "timeframe": "12 minggu"}, {"metric": "Kecepatan jalan", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Stabil tanpa jatuh 2 minggu", "action": "Tambah durasi atau kompleksitas latihan keseimbangan"}'::jsonb,
  'Latihan sebaiknya dilakukan saat obat sedang bekerja optimal. Gerakan dengan langkah besar dan sengaja membantu melatih otak mengatasi kekakuan gerak.',
  'Gerakan yang disengaja dan konsisten membantu tubuh Anda tetap lincah.',
  '{"day_1": "20 menit", "week_12": "45 menit"}'::jsonb,
  ARRAY['Movement Disorder Society Guidelines','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'neurology',
  'pasca_stroke',
  ARRAY['STROKE']::diagnosis_type_enum[],
  'Post-Stroke',
  'Pasca Stroke',
  'Program Rehabilitasi Fisik Pasca Stroke',
  'pemula',
  'Pasien pasca stroke fase subakut-kronik, kondisi medis stabil, sudah dievaluasi tim rehabilitasi medik',
  '[{"id": "motor_function", "label_id": "Memulihkan fungsi motorik sisi yang terkena"}, {"id": "functional_capacity", "label_id": "Meningkatkan kapasitas aerobik dan mobilitas"}, {"id": "fall_prevention", "label_id": "Mengurangi risiko jatuh"}]'::jsonb,
  '{"frequency": "3-5x/minggu (aerobik) + 2-3x/minggu (penguatan/keseimbangan)", "intensity": {"method": "RPE", "target": "11-14", "notes": "Sesuai rekomendasi tim rehabilitasi medik"}, "time": "20-40 menit/sesi", "type": ["Latihan gaya berjalan (dengan/tanpa alat bantu)", "Sepeda statis", "Latihan penguatan sisi lemah", "Latihan keseimbangan"]}'::jsonb,
  '{"duration_minutes": 10, "steps": ["Mobilisasi sendi", "Peregangan ringan sisi yang lemah"]}'::jsonb,
  '{"description": "Latihan task-specific (spesifik pada aktivitas yang ingin dipulihkan) dikombinasikan dengan latihan aerobik dan penguatan, idealnya dalam program rehabilitasi terstruktur.", "weekly_progression": [{"period": "Fase subakut", "duration_minutes": 20, "notes": "Dengan supervisi fisioterapis"}, {"period": "Fase kronik", "duration_minutes": 40, "notes": "Semi-mandiri dengan evaluasi berkala"}], "resistance_details": [{"exercise": "Latihan penguatan sisi lemah (sesuai arahan fisioterapis)", "muscle_group": "Sesuai sisi yang terkena", "sets": 2, "reps": 10, "rest_seconds": 60}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan", "Istirahat"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan lembut sisi yang spastik/kaku"]}'::jsonb,
  '[]'::jsonb,
  '{"hemiparesis_berat": "Gunakan alat bantu jalan dan pendampingan penuh", "spastisitas": "Koordinasi dengan fisioterapis untuk teknik peregangan yang tepat"}'::jsonb,
  '["Gejala neurologis baru/memburuk (curiga stroke berulang — kegawatdaruratan)", "Nyeri dada", "Sesak napas berat", "Jatuh", "Sakit kepala hebat mendadak"]'::jsonb,
  '{"absolute": ["Kondisi neurologis akut tidak stabil", "Kecurigaan stroke berulang - rujuk gawat darurat"], "relative": ["Kardiovaskular tidak stabil"]}'::jsonb,
  '[{"metric": "Fungsi motorik (Fugl-Meyer/skala fungsional)", "direction": "increase", "target": "peningkatan skor", "timeframe": "individual, evaluasi berkala"}, {"metric": "Mobilitas fungsional", "direction": "increase", "target": "peningkatan kemandirian ADL", "timeframe": "individual"}]'::jsonb,
  '{"trigger": "Evaluasi tim rehabilitasi medik menunjukkan kesiapan", "action": "Tingkatkan kompleksitas/durasi latihan"}'::jsonb,
  'Pemulihan pasca stroke membutuhkan latihan yang berulang dan konsisten — otak dan otot belajar kembali gerakan melalui pengulangan. Libatkan keluarga untuk mendukung latihan di rumah.',
  'Setiap pengulangan gerakan adalah langkah kecil menuju kemandirian yang lebih besar.',
  '{"phase_subacute": "20 menit (terawasi)", "phase_chronic": "40 menit"}'::jsonb,
  ARRAY['AHA/ASA Stroke Rehabilitation Guidelines','American Physical Therapy Association']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'neurology',
  'multiple_sclerosis',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Multiple Sclerosis',
  'Multiple Sclerosis',
  'Program Latihan Adaptif untuk Multiple Sclerosis',
  'pemula',
  'Pasien MS dalam kondisi remisi/stabil, tanpa relaps aktif',
  '[{"id": "fatigue", "label_id": "Mengurangi kelelahan"}, {"id": "mobility", "label_id": "Mempertahankan mobilitas dan kekuatan otot"}, {"id": "quality_of_life", "label_id": "Meningkatkan kualitas hidup"}]'::jsonb,
  '{"frequency": "3-4x/minggu", "intensity": {"method": "RPE", "target": "10-13, ringan-sedang", "notes": "Hindari overheating (suhu tubuh naik dapat memperburuk gejala sementara - fenomena Uhthoff)"}, "time": "20-30 menit/sesi", "type": ["Berenang (air sejuk)", "Sepeda statis", "Latihan penguatan ringan", "Yoga adaptif"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi ringan di lingkungan sejuk"]}'::jsonb,
  '{"description": "Latihan di lingkungan sejuk (kolam renang suhu sedang, ruangan ber-AC) untuk menghindari peningkatan suhu tubuh yang dapat memicu perburukan gejala sementara.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Ringan, pantau kelelahan"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Bertahap sesuai energi"}], "resistance_details": [{"exercise": "Resistance band ringan", "muscle_group": "Otot besar", "sets": 2, "reps": 10, "rest_seconds": 90}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Pendinginan di lingkungan sejuk"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan lembut untuk spastisitas"]}'::jsonb,
  '[]'::jsonb,
  '{"spastisitas": "Koordinasi dengan fisioterapis untuk teknik peregangan", "fatigue_berat": "Gunakan prinsip energy conservation, latihan sesi pendek terbagi"}'::jsonb,
  '["Gejala neurologis baru/memburuk signifikan (curiga relaps)", "Kelelahan ekstrem tidak membaik dengan istirahat", "Gangguan penglihatan mendadak", "Suhu tubuh meningkat drastis dengan gejala memburuk"]'::jsonb,
  '{"absolute": ["Relaps aktif"], "relative": ["Kelelahan berat hari itu - sesuaikan atau tunda"]}'::jsonb,
  '[{"metric": "Tingkat kelelahan (Fatigue Severity Scale)", "direction": "decrease", "target": "penurunan skor", "timeframe": "8-12 minggu"}, {"metric": "Kekuatan otot", "direction": "maintain", "target": "stabil/meningkat", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Tanpa perburukan gejala 2 minggu", "action": "Tambah durasi 10%"}'::jsonb,
  'Berlatihlah di lingkungan sejuk dan hindari waktu terpanas hari itu, karena suhu tubuh yang naik dapat memicu gejala memburuk sementara. Ini bukan tanda kerusakan permanen dan akan membaik setelah tubuh mendingin.',
  'Latihan yang disesuaikan membantu Anda tetap bugar tanpa memicu gejala berlebih.',
  '{"day_1": "15 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['National MS Society Exercise Guidelines','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'geriatric',
  'frailty',
  ARRAY['GERIATRIC']::diagnosis_type_enum[],
  'Frailty',
  'Frailty (Kerapuhan Lansia)',
  'Program Multikomponen untuk Lansia Frail',
  'pemula',
  'Lansia dengan sindrom frailty (memenuhi ≥3 kriteria Fried: kelemahan, kelelahan, penurunan aktivitas, gaya berjalan lambat, penurunan berat badan)',
  '[{"id": "function", "label_id": "Meningkatkan kapasitas fungsional dan kemandirian"}, {"id": "muscle_strength", "label_id": "Meningkatkan kekuatan otot"}, {"id": "fall_prevention", "label_id": "Mengurangi risiko jatuh"}]'::jsonb,
  '{"frequency": "3x/minggu (terstruktur) + aktivitas ringan harian", "intensity": {"method": "RPE", "target": "10-13, mulai sangat ringan", "notes": "Program multikomponen: latihan aerobik, resistance, keseimbangan, fleksibilitas"}, "time": "20-30 menit/sesi", "type": ["Latihan fungsional (sit-to-stand)", "Latihan keseimbangan", "Jalan kaki dengan/tanpa alat bantu"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi sendi duduk", "Pemanasan ringan"]}'::jsonb,
  '{"description": "Program multikomponen (aerobik + resistance + keseimbangan) idealnya dengan supervisi awal, sangat bertahap. Prioritaskan keamanan.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 10, "notes": "Sangat ringan, sebagian besar duduk"}, {"period": "Minggu 12", "duration_minutes": 30, "notes": "Bertahap sesuai toleransi dan evaluasi"}], "resistance_details": [{"exercise": "Sit-to-stand dari kursi tinggi", "muscle_group": "Tungkai", "sets": 1, "reps": 5, "rest_seconds": 90, "notes": "Dengan pendampingan"}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Istirahat duduk"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan sambil duduk"]}'::jsonb,
  '[]'::jsonb,
  '{"risiko_jatuh_sangat_tinggi": "Semua latihan dengan pendampingan langsung, gunakan kursi/dinding untuk pegangan", "gangguan_kognitif": "Instruksi sederhana, satu langkah pada satu waktu"}'::jsonb,
  '["Jatuh saat latihan", "Nyeri dada", "Sesak napas tidak wajar", "Kebingungan mendadak", "Kelelahan ekstrem"]'::jsonb,
  '{"absolute": ["Kondisi medis akut tidak stabil"], "relative": ["Frailty sangat berat - mulai dengan evaluasi tim geriatri komprehensif"]}'::jsonb,
  '[{"metric": "Kecepatan jalan", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}, {"metric": "Kekuatan genggam", "direction": "increase", "target": "peningkatan bertahap", "timeframe": "12 minggu"}]'::jsonb,
  '{"trigger": "Stabil tanpa jatuh/keluhan 2 minggu, evaluasi positif", "action": "Tambah durasi 5 menit atau repetisi +1"}'::jsonb,
  'Latihan sekecil apa pun, seperti berdiri dari kursi beberapa kali sehari, dapat membantu Anda tetap mandiri. Selalu lakukan dengan pendamping di dekat Anda.',
  'Setiap gerakan kecil hari ini adalah langkah menuju kemandirian yang lebih besar.',
  '{"day_1": "10 menit", "week_12": "30 menit"}'::jsonb,
  ARRAY['WHO ICOPE Guidelines','ACSM Geriatric Exercise']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'geriatric',
  'risiko_jatuh',
  ARRAY['GERIATRIC']::diagnosis_type_enum[],
  'Fall Risk',
  'Risiko Jatuh',
  'Program Latihan Keseimbangan untuk Pencegahan Jatuh',
  'pemula',
  'Lansia dengan riwayat jatuh atau risiko jatuh tinggi (gangguan keseimbangan, gaya berjalan tidak stabil)',
  '[{"id": "balance", "label_id": "Meningkatkan keseimbangan"}, {"id": "fall_prevention", "label_id": "Mengurangi frekuensi dan risiko jatuh"}, {"id": "confidence", "label_id": "Meningkatkan kepercayaan diri bergerak"}]'::jsonb,
  '{"frequency": "3x/minggu (terstruktur) + latihan keseimbangan harian singkat", "intensity": {"method": "RPE", "target": "10-12", "notes": "Latihan keseimbangan progresif (Otago Exercise Programme atau setara)"}, "time": "20-30 menit/sesi", "type": ["Latihan keseimbangan berdiri", "Latihan penguatan tungkai", "Jalan dengan tantangan keseimbangan ringan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Mobilisasi sendi", "Jalan pelan dengan pegangan"]}'::jsonb,
  '{"description": "Latihan keseimbangan progresif seperti berdiri satu kaki (dengan pegangan), tandem walk, dan penguatan tungkai, mengikuti prinsip program terstruktur (mis. Otago).", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 15, "notes": "Dengan pegangan penuh"}, {"period": "Minggu 12", "duration_minutes": 30, "notes": "Tantangan keseimbangan meningkat sesuai evaluasi"}], "resistance_details": [{"exercise": "Heel-to-toe walk (tandem walk) dengan pegangan", "muscle_group": "Keseimbangan/tungkai", "sets": 2, "reps": "10 langkah", "rest_seconds": 60}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Duduk istirahat"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan ringan tungkai"]}'::jsonb,
  '[]'::jsonb,
  '{"gangguan_penglihatan": "Pastikan pencahayaan baik dan area latihan bebas hambatan", "gangguan_kognitif": "Instruksi sederhana dan pengawasan lebih ketat"}'::jsonb,
  '["Jatuh saat latihan", "Pusing berat/vertigo", "Nyeri dada", "Kebingungan mendadak"]'::jsonb,
  '{"absolute": ["Kondisi akut tidak stabil"], "relative": ["Vertigo aktif belum dievaluasi"]}'::jsonb,
  '[{"metric": "Skor keseimbangan (Berg Balance Scale/TUG test)", "direction": "increase", "target": "perbaikan skor", "timeframe": "12 minggu"}, {"metric": "Kejadian jatuh", "direction": "decrease", "target": "penurunan frekuensi jatuh", "timeframe": "6-12 bulan"}]'::jsonb,
  '{"trigger": "Stabil tanpa jatuh 2 minggu", "action": "Kurangi bantuan pegangan secara bertahap atau tambah kompleksitas"}'::jsonb,
  'Pastikan rumah bebas dari hambatan seperti karpet longgar atau lantai licin. Gunakan alas kaki yang stabil, dan lakukan latihan keseimbangan di dekat pegangan yang kokoh.',
  'Keseimbangan yang lebih baik berarti langkah yang lebih percaya diri setiap hari.',
  '{"day_1": "15 menit", "week_12": "30 menit"}'::jsonb,
  ARRAY['Otago Exercise Programme','CDC STEADI Initiative','WHO ICOPE']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'women',
  'kehamilan',
  ARRAY['PREGNANCY']::diagnosis_type_enum[],
  'Pregnancy',
  'Kehamilan',
  'Program Aktivitas Fisik Aman Selama Kehamilan',
  'pemula',
  'Ibu hamil dengan kehamilan risiko rendah, sudah mendapat izin dokter kandungan',
  '[{"id": "fitness", "label_id": "Mempertahankan kebugaran kardiovaskular"}, {"id": "weight", "label_id": "Membantu kontrol penambahan berat badan sesuai target"}, {"id": "labor_prep", "label_id": "Mempersiapkan tubuh untuk persalinan"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "Talk Test / RPE", "target": "11-13, masih bisa bicara nyaman", "notes": "Hindari kepanasan berlebih dan dehidrasi"}, "time": "20-30 menit/sesi", "type": ["Jalan kaki", "Berenang", "Prenatal yoga", "Latihan dasar panggul (Kegel)"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Peregangan ringan"]}'::jsonb,
  '{"description": "Hindari posisi terlentang lama setelah trimester pertama, olahraga kontak, dan aktivitas dengan risiko jatuh tinggi.", "weekly_progression": [{"period": "Trimester 1", "duration_minutes": 20, "notes": "Sesuai kebiasaan sebelumnya, sesuaikan bila mual"}, {"period": "Trimester 2-3", "duration_minutes": 30, "notes": "Intensitas dipertahankan, bukan ditingkatkan drastis"}], "resistance_details": [{"exercise": "Kegel (dasar panggul)", "muscle_group": "Otot dasar panggul", "sets": 3, "reps": 10, "rest_seconds": 30}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Hidrasi cukup"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan lembut, hindari peregangan berlebihan (relaksin meningkat)"]}'::jsonb,
  '[]'::jsonb,
  '{"kehamilan_risiko_tinggi": "Konsultasi dokter kandungan sebelum memulai/melanjutkan program apa pun", "preeklampsia": "Hindari olahraga hingga dievaluasi dan diizinkan dokter"}'::jsonb,
  '["Perdarahan vagina", "Kontraksi teratur sebelum waktunya", "Cairan ketuban pecah", "Sesak napas berat sebelum aktivitas", "Nyeri dada", "Sakit kepala hebat", "Nyeri/bengkak betis satu sisi (curiga trombosis)", "Penurunan gerakan janin"]'::jsonb,
  '{"absolute": ["Preeklampsia", "Plasenta previa setelah 26 minggu", "Ketuban pecah dini", "Persalinan prematur", "Perdarahan persisten trimester 2-3"], "relative": ["Anemia berat", "Riwayat persalinan prematur"]}'::jsonb,
  '[{"metric": "Penambahan berat badan", "direction": "maintain", "target": "sesuai rekomendasi IMT pra-hamil", "timeframe": "per trimester"}, {"metric": "Kebugaran umum", "direction": "maintain", "target": "stabil, nyaman beraktivitas", "timeframe": "sepanjang kehamilan"}]'::jsonb,
  '{"trigger": "Tidak ada — pertahankan intensitas, jangan tingkatkan drastis selama kehamilan", "action": "Sesuaikan turun bila muncul ketidaknyamanan"}'::jsonb,
  'Tetap aktif selama kehamilan risiko rendah aman dan bermanfaat untuk ibu dan janin. Dengarkan tubuh Anda — jika merasa sangat lelah atau tidak nyaman, kurangi intensitas.',
  'Tubuh yang aktif membantu mempersiapkan Anda menghadapi persalinan dengan lebih siap.',
  '{"trimester_1": "20 menit", "trimester_2_3": "30 menit"}'::jsonb,
  ARRAY['ACOG Guidelines','WHO Physical Activity Guidelines']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'women',
  'postpartum',
  ARRAY['LACTATION']::diagnosis_type_enum[],
  'Postpartum',
  'Pasca Persalinan (Postpartum)',
  'Program Pemulihan Fisik Pasca Persalinan',
  'pemula',
  'Ibu pasca persalinan normal (mulai ~6 minggu) atau pasca sesar (mulai ~8-10 minggu, sesuai izin dokter)',
  '[{"id": "core_recovery", "label_id": "Memulihkan kekuatan otot core dan dasar panggul"}, {"id": "fitness", "label_id": "Mengembalikan kebugaran secara bertahap"}, {"id": "mental_health", "label_id": "Mendukung kesehatan mental (mengurangi risiko baby blues/depresi)"}]'::jsonb,
  '{"frequency": "3-5x/minggu", "intensity": {"method": "RPE", "target": "10-13, mulai ringan", "notes": "Mulai dari latihan dasar panggul dan core sebelum latihan intensitas lebih tinggi"}, "time": "15-30 menit/sesi", "type": ["Jalan kaki", "Latihan dasar panggul (Kegel)", "Latihan core ringan", "Yoga postnatal"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Latihan pernapasan"]}'::jsonb,
  '{"description": "Mulai dari latihan dasar panggul dan aktivasi core ringan (transversus abdominis) sebelum kembali ke latihan intensitas lebih tinggi. Periksa diastasis recti bila ada.", "weekly_progression": [{"period": "Minggu 6-8", "duration_minutes": 15, "notes": "Dasar panggul dan jalan kaki ringan"}, {"period": "Minggu 12+", "duration_minutes": 30, "notes": "Bertahap tambah intensitas sesuai evaluasi"}], "resistance_details": [{"exercise": "Kegel", "muscle_group": "Dasar panggul", "sets": 3, "reps": 10, "rest_seconds": 30}, {"exercise": "Pelvic tilt", "muscle_group": "Core", "sets": 2, "reps": 10, "rest_seconds": 45}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan lembut bahu dan punggung (sering tegang karena menyusui)"]}'::jsonb,
  '[]'::jsonb,
  '{"pasca_sesar": "Tunggu izin dokter (biasanya 8-10 minggu), hindari latihan perut intensif hingga luka pulih", "diastasis_recti": "Hindari sit-up penuh, fokus pada latihan core yang aman (koordinasi dengan fisioterapis)"}'::jsonb,
  '["Perdarahan vagina meningkat/berubah warna terang", "Nyeri perut hebat", "Demam", "Nyeri/bengkak tungkai satu sisi", "Sesak napas", "Tanda-tanda depresi postpartum berat"]'::jsonb,
  '{"absolute": ["Perdarahan postpartum aktif", "Infeksi luka operasi/jahitan"], "relative": ["Diastasis recti berat belum dievaluasi"]}'::jsonb,
  '[{"metric": "Kekuatan dasar panggul", "direction": "increase", "target": "perbaikan fungsi", "timeframe": "12 minggu"}, {"metric": "Kesejahteraan mental", "direction": "increase", "target": "perbaikan mood/energi", "timeframe": "berkelanjutan"}]'::jsonb,
  '{"trigger": "Pemulihan luka baik dan tanpa nyeri 2 minggu", "action": "Tambah durasi/intensitas bertahap"}'::jsonb,
  'Pemulihan pasca persalinan butuh waktu — mulailah dari latihan dasar panggul sebelum kembali ke aktivitas yang lebih berat. Aktivitas fisik ringan juga membantu suasana hati Anda.',
  'Tubuh Anda baru saja melakukan hal luar biasa — beri waktu untuk pulih dengan lembut namun konsisten.',
  '{"week_6_8": "15 menit", "week_12_plus": "30 menit"}'::jsonb,
  ARRAY['ACOG Postpartum Guidelines','Royal Australian and New Zealand College of Obstetricians']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'women',
  'menopause',
  ARRAY['OTHER']::diagnosis_type_enum[],
  'Menopause',
  'Menopause',
  'Program Latihan Komprehensif untuk Wanita Menopause',
  'pemula',
  'Wanita perimenopause/menopause, dengan perhatian pada kesehatan tulang, jantung, dan berat badan',
  '[{"id": "bone_health", "label_id": "Menjaga kepadatan tulang"}, {"id": "cv_health", "label_id": "Menjaga kesehatan kardiovaskular"}, {"id": "weight", "label_id": "Membantu kontrol berat badan"}, {"id": "vasomotor_symptoms", "label_id": "Membantu mengurangi gejala vasomotor (hot flashes)"}]'::jsonb,
  '{"frequency": "5x/minggu (aerobik) + 2-3x/minggu (resistance/weight-bearing)", "intensity": {"method": "RPE", "target": "11-14", "notes": "Kombinasi aerobik dan latihan beban untuk tulang dan otot"}, "time": "30 menit/sesi", "type": ["Jalan cepat", "Resistance training", "Latihan weight-bearing", "Yoga"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Mobilisasi sendi"]}'::jsonb,
  '{"description": "Kombinasi aerobik untuk kesehatan jantung dan resistance/weight-bearing untuk kepadatan tulang, penting karena penurunan estrogen mempercepat kehilangan massa tulang dan otot.", "weekly_progression": [{"period": "Minggu 1-2", "duration_minutes": 20, "notes": "Membangun kebiasaan"}, {"period": "Minggu 8", "duration_minutes": 30, "notes": "Target FITT tercapai"}], "resistance_details": [{"exercise": "Squat", "muscle_group": "Tungkai", "sets": 2, "reps": 10, "rest_seconds": 60}, {"exercise": "Resistance band row", "muscle_group": "Punggung", "sets": 2, "reps": 10, "rest_seconds": 60}]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Jalan pelan", "Pendinginan"]}'::jsonb,
  '{"duration_minutes": 5, "steps": ["Peregangan seluruh tubuh"]}'::jsonb,
  '[]'::jsonb,
  '{"osteoporosis_komorbid": "Hindari latihan high-impact dan fleksi tulang belakang berlebihan", "hot_flashes_berat": "Latihan di lingkungan sejuk, kenakan pakaian yang menyerap keringat"}'::jsonb,
  '["Nyeri dada", "Sesak napas tidak wajar", "Perdarahan vagina abnormal pasca-menopause (segera periksa ke dokter)", "Nyeri tulang mendadak"]'::jsonb,
  '{"absolute": [], "relative": ["Penyakit kardiovaskular belum dievaluasi", "Osteoporosis berat - sesuaikan jenis latihan"]}'::jsonb,
  '[{"metric": "Berat badan/lingkar perut", "direction": "maintain", "target": "sesuai target individual", "timeframe": "berkelanjutan"}, {"metric": "Densitas tulang", "direction": "maintain", "target": "stabil", "timeframe": "1-2 tahun"}]'::jsonb,
  '{"trigger": "Toleransi baik 2 minggu", "action": "Tambah durasi 10% atau beban ringan"}'::jsonb,
  'Latihan beban teratur membantu memperlambat pengeroposan tulang dan otot yang sering terjadi setelah menopause, sekaligus membantu mengelola berat badan dan suasana hati.',
  'Fase ini adalah kesempatan baru untuk berinvestasi pada kekuatan dan kesehatan jangka panjang Anda.',
  '{"day_1": "20 menit", "week_8": "30 menit"}'::jsonb,
  ARRAY['North American Menopause Society','ACSM']
) ON CONFLICT (diagnosis_code, version) DO NOTHING;

INSERT INTO exercise_programs (category_id, diagnosis_code, linked_diagnosis_types, diagnosis_name_en, diagnosis_name_id, program_name, difficulty_level, target_patient, goals, fitt, warmup, core_exercise, cooldown, stretching, media_references, modifications, red_flags, contraindications, monitoring_targets, progression_rule, patient_education, motivation_quote, daily_target_schedule, evidence_references) VALUES (
  'pediatric',
  'obesitas_anak',
  ARRAY['PEDIATRIC','OBESITY']::diagnosis_type_enum[],
  'Childhood Obesity',
  'Obesitas pada Anak',
  'Program Aktivitas Fisik Menyenangkan untuk Anak dengan Obesitas',
  'pemula',
  'Anak usia 6-18 tahun dengan IMT di atas persentil 95 sesuai usia dan jenis kelamin',
  '[{"id": "weight", "label_id": "Membantu perbaikan status berat badan secara bertahap"}, {"id": "fitness", "label_id": "Meningkatkan kebugaran dan keterampilan motorik"}, {"id": "habit", "label_id": "Membentuk kebiasaan aktif jangka panjang"}]'::jsonb,
  '{"frequency": "Setiap hari (total 60 menit/hari sesuai anjuran WHO)", "intensity": {"method": "RPE anak / observasi", "target": "Sedang-berat, boleh terbagi beberapa sesi", "notes": "Fokus pada permainan aktif, bukan ''olahraga terstruktur'' semata"}, "time": "60 menit/hari (boleh terbagi)", "type": ["Permainan aktif (kejar-kejaran, lompat tali)", "Bersepeda", "Berenang", "Olahraga tim sesuai minat anak"]}'::jsonb,
